<template><div class="page"><header><h1>{{ course?.name || '课程作业' }}</h1></header><StudentGradeTrend :scores="courseScores"/><section class="panel"><div class="panel-head"><h2>课程作业</h2><span>{{ assignments.length }} 项作业</span></div><button v-for="item in assignments" :key="item.id" class="assignment" @click="router.push('/student/assignment/'+item.id)"><div class="icon">作业</div><div class="main"><h3>{{ item.title }}</h3><p>{{ item.description || '暂无作业说明' }}</p></div><i :class="item.teamFormation ? 'forming' : 'pending'">{{ item.teamFormation ? '组队中' : '待提交' }}</i></button></section></div></template>
<script setup>
import { computed,onMounted,ref } from 'vue';import { useRoute,useRouter } from 'vue-router';import StudentGradeTrend from '@/components/student/StudentGradeTrend.vue';import { getAssignments,getCourses,getScores } from '@/api/student';import { getErrorMessage } from '@/api/response'
const route=useRoute();const router=useRouter();const courses=ref([]);const assignments=ref([]);const scores=ref([]);const errorMessage=ref('');const course=computed(()=>courses.value.find(item=>String(item.id)===String(route.params.courseId)));const courseScores=computed(()=>scores.value.filter(item=>item.courseName===course.value?.name));onMounted(async()=>{try{[courses.value,assignments.value,scores.value]=await Promise.all([getCourses(),getAssignments(route.params.courseId),getScores()])}catch(error){errorMessage.value=getErrorMessage(error,'课程数据加载失败')}})
</script>
<style scoped>.page{max-width:1120px;margin:0 auto}header{margin-bottom:25px}header h1{color:#263b53}.panel{overflow:hidden;border-radius:9px;background:#fff}.panel-head{display:flex;justify-content:space-between;padding:19px 22px;border-bottom:1px solid #edf1f4}.assignment{display:flex;width:100%;align-items:center;gap:16px;padding:18px 22px;border:0;border-bottom:1px solid #edf1f4;background:#fff;text-align:left;cursor:pointer}.icon{padding:12px;border-radius:9px;color:#356798;background:#eaf2fa}.main{flex:1}.main p{color:#98a5b3}.assignment i{padding:5px 10px;border-radius:99px;font-style:normal}.forming{color:#356798;background:#eaf2fa}.pending{color:#9b6b29;background:#fff6e8}</style>
